"""
Colab & Cloud GPU Training Bridge: Malayalam LLM QLoRA / Unsloth Fine-Tuner
Equipped with an automated Google Drive Relay-Race Checkpointing Loop
to bypass Colab 12-hour session timeouts and disconnects.
"""

COLAB_TRAINER_TEMPLATE = '''# ==============================================================================
# 🚀 MALAYALAM LLM QLoRA RELAY-RACE FINE-TUNING PIPELINE (Colab / Kaggle / Cloud)
# Generated by Visual CrewAI Studio // Malayalam Corpus Builder & Trainer
# ==============================================================================

# Step 1: Install Optimized Fast-Inference & Training Dependencies
# !pip install -q "unsloth[colab-new] @ git+https://github.com/unslothai/unsloth.git"
# !pip install -q --no-deps "xformers<0.0.27" "trl<0.9.0" peft accelerate bitsandbytes datasets

import os
import sys
import time
import glob
import torch
from datasets import load_dataset, Dataset
from transformers import TrainingArguments, DataCollatorForSeq2Seq
from trl import SFTTrainer

# ------------------------------------------------------------------------------
# 1. Configuration & Relay-Race Checkpointing State
# ------------------------------------------------------------------------------
MODEL_NAME = "unsloth/llama-3-8b-Instruct-bnb-4bit" # or "unsloth/gemma-2-9b-bnb-4bit"
MAX_SEQ_LENGTH = 2048
LOAD_IN_4BIT = True
LORA_R = 16
LORA_ALPHA = 32
LORA_DROPOUT = 0.05
LEARNING_RATE = 2e-4
BATCH_SIZE = 2
GRADIENT_ACCUMULATION_STEPS = 4
MAX_STEPS = 500
SAVE_STEPS = 50

# Persistent Google Drive Mount for Session Disconnect Recovery
GDRIVE_CHECKPOINT_DIR = "/content/drive/MyDrive/malayalam_llm_checkpoints"

def ensure_gdrive_mounted():
    try:
        from google.colab import drive
        print("🔗 Mounting Google Drive for relay-race checkpoint persistence...")
        drive.mount('/content/drive', force_remount=False)
        os.makedirs(GDRIVE_CHECKPOINT_DIR, exist_ok=True)
        print(f"✅ Checkpoint directory ready: {GDRIVE_CHECKPOINT_DIR}")
    except ImportError:
        print("⚠️ Not running in Google Colab. Using local ./checkpoints/ directory.")
        os.makedirs("./checkpoints", exist_ok=True)
        return "./checkpoints"
    return GDRIVE_CHECKPOINT_DIR

CHECKPOINT_PATH = ensure_gdrive_mounted()

# ------------------------------------------------------------------------------
# 2. Check for Previous Checkpoints (Relay-Race Resume)
# ------------------------------------------------------------------------------
def find_latest_checkpoint(checkpoint_dir):
    checkpoints = glob.glob(os.path.join(checkpoint_dir, "checkpoint-*"))
    if not checkpoints:
        return None
    # Sort by step number
    checkpoints.sort(key=lambda x: int(x.split("-")[-1]))
    latest = checkpoints[-1]
    print(f"🔁 Found existing checkpoint! Resuming relay race from: {latest}")
    return latest

RESUME_FROM_CHECKPOINT = find_latest_checkpoint(CHECKPOINT_PATH)

# ------------------------------------------------------------------------------
# 3. Model & Fast LoRA Adapter Setup
# ------------------------------------------------------------------------------
try:
    from unsloth import FastLanguageModel
    print(f"📦 Loading {MODEL_NAME} via Unsloth FastLanguageModel...")
    model, tokenizer = FastLanguageModel.from_pretrained(
        model_name=MODEL_NAME,
        max_seq_length=MAX_SEQ_LENGTH,
        dtype=None,
        load_in_4bit=LOAD_IN_4BIT
    )

    model = FastLanguageModel.get_peft_model(
        model,
        r=LORA_R,
        target_modules=["q_proj", "k_proj", "v_proj", "o_proj", "gate_proj", "up_proj", "down_proj"],
        lora_alpha=LORA_ALPHA,
        lora_dropout=LORA_DROPOUT,
        bias="none",
        use_gradient_checkpointing="unsloth",
        random_state=3407
    )
except Exception as e:
    print(f"⚠️ Unsloth not found ({e}). Falling back to standard PEFT / BitsAndBytes...")
    from transformers import AutoModelForCausalLM, AutoTokenizer, BitsAndBytesConfig
    from peft import LoraConfig, get_peft_model, prepare_model_for_kbit_training

    bnb_config = BitsAndBytesConfig(
        load_in_4bit=True,
        bnb_4bit_quant_type="nf4",
        bnb_4bit_compute_dtype=torch.float16
    )
    tokenizer = AutoTokenizer.from_pretrained(MODEL_NAME)
    model = AutoModelForCausalLM.from_pretrained(MODEL_NAME, quantization_config=bnb_config, device_map="auto")
    model = prepare_model_for_kbit_training(model)
    peft_config = LoraConfig(
        r=LORA_R, lora_alpha=LORA_ALPHA, lora_dropout=LORA_DROPOUT,
        target_modules=["q_proj", "v_proj"], bias="none", task_type="CAUSAL_LM"
    )
    model = get_peft_model(model, peft_config)

# Ensure tokenizer padding
if tokenizer.pad_token is None:
    tokenizer.pad_token = tokenizer.eos_token

# ------------------------------------------------------------------------------
# 4. Load & Format Approved Malayalam Dataset
# ------------------------------------------------------------------------------
# Formats pretraining / instruction pairs into native Malayalam prompt template
PROMPT_TEMPLATE = """### നിർദ്ദേശം (Instruction):
{instruction}

### പ്രതികരണം (Response):
{output}"""

def formatting_prompts_func(batch):
    instructions = batch.get("instruction", [])
    outputs = batch.get("output", [])
    texts = []
    for inst, out in zip(instructions, outputs):
        t = PROMPT_TEMPLATE.format(instruction=inst, output=out) + tokenizer.eos_token
        texts.append(t)
    return {"text": texts}

# Replace with your approved dataset json or upload path
DATASET_PATH = "./approved_malayalam_training_data.json"

if os.path.exists(DATASET_PATH):
    print(f"📖 Loading approved dataset from: {DATASET_PATH}")
    dataset = load_dataset("json", data_files=DATASET_PATH, split="train")
else:
    print("ℹ️ Mock dataset generated for dry-run verification...")
    mock_data = [
        {"instruction": "കേരളത്തിന്റെ തലസ്ഥാനം ഏതാണ്?", "output": "കേരളത്തിന്റെ തലസ്ഥാനം തിരുവനന്തപുരമാണ്."},
        {"instruction": "മലയാള ഭാഷയുടെ പ്രത്യേകതകൾ എന്തൊക്കെയാണ്?", "output": "ദ്രാവിഡ ഭാഷാ കുടുംബത്തിൽപ്പെട്ട സമ്പന്നമായ സാഹിത്യ പാരമ്പര്യമുള്ള ഭാഷയാണ് മലയാളം."}
    ]
    dataset = Dataset.from_list(mock_data)

formatted_dataset = dataset.map(formatting_prompts_func, batched=True)
print(f"✅ Dataset formatted: {len(formatted_dataset)} records ready for training.")

# ------------------------------------------------------------------------------
# 5. Training Arguments with Relay-Race Checkpoint Automation
# ------------------------------------------------------------------------------
training_args = TrainingArguments(
    output_dir=CHECKPOINT_PATH,
    per_device_train_batch_size=BATCH_SIZE,
    gradient_accumulation_steps=GRADIENT_ACCUMULATION_STEPS,
    warmup_steps=10,
    max_steps=MAX_STEPS,
    learning_rate=LEARNING_RATE,
    fp16=not torch.cuda.is_bf16_supported(),
    bf16=torch.cuda.is_bf16_supported(),
    logging_steps=10,
    save_strategy="steps",
    save_steps=SAVE_STEPS,
    save_total_limit=3, # Keep 3 newest checkpoints to conserve Drive space
    optim="adamw_8bit",
    weight_decay=0.01,
    lr_scheduler_type="linear",
    seed=42,
    report_to="none"
)

trainer = SFTTrainer(
    model=model,
    tokenizer=tokenizer,
    train_dataset=formatted_dataset,
    dataset_text_field="text",
    max_seq_length=MAX_SEQ_LENGTH,
    args=training_args
)

# ------------------------------------------------------------------------------
# 6. Run Training & Safe Checkpointing
# ------------------------------------------------------------------------------
print("🔥 Launching Malayalam LLM Fine-Tuning Relay Race...")
trainer.train(resume_from_checkpoint=RESUME_FROM_CHECKPOINT)

# Final Save
FINAL_SAVE_PATH = os.path.join(CHECKPOINT_PATH, "malayalam_lora_final")
print(f"💾 Saving final LoRA weights to: {FINAL_SAVE_PATH}")
model.save_pretrained(FINAL_SAVE_PATH)
tokenizer.save_pretrained(FINAL_SAVE_PATH)
print("🎉 Malayalam LLM Training & Relay Checkpoint Complete!")
'''

def get_colab_script() -> str:
    """Returns the copy-pasteable Colab training script."""
    return COLAB_TRAINER_TEMPLATE


if __name__ == "__main__":
    print(get_colab_script())
